package com.bplus.share;
import android.app.*;import android.os.*;import java.util.concurrent.*;
/** Every outgoing original file passes this gate. No resumed activity means no unattended send. */
public final class FileConsent {
 private static volatile Activity active;
 public static void init(Application app){app.registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){active=a;}public void onActivityPaused(Activity a){if(active==a)active=null;}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){if(active==a)active=null;}});}
 public static synchronized boolean ask(String destination,String name,long bytes){Activity a=active;if(a==null||Looper.myLooper()==Looper.getMainLooper())return false;CountDownLatch done=new CountDownLatch(1);boolean[] yes={false};android.app.AlertDialog[] shown={null};a.runOnUiThread(()->{if(active!=a||a.isFinishing()||a.isDestroyed()){done.countDown();return;}AppDialog d=new AppDialog(a);d.setTitle(R.string.confirm_file_title).setMessage(a.getString(R.string.confirm_file_to,destination)+"\n\n"+name+"\n"+Ui.fmtSize(bytes)).setNegativeButton(R.string.cancel,(x,n)->done.countDown()).setPositiveButton(R.string.send_now,(x,n)->{yes[0]=active==a;done.countDown();});android.app.AlertDialog dialog=d.create();shown[0]=dialog;dialog.setOnCancelListener(x->done.countDown());dialog.show();});try{if(!done.await(120,TimeUnit.SECONDS)){a.runOnUiThread(()->{if(shown[0]!=null)shown[0].dismiss();});return false;}}catch(InterruptedException e){Thread.currentThread().interrupt();return false;}return yes[0]&&active==a;}
}
